        give_souvenir: { title: '送伴手礼', category: 'social', icon: 'fas fa-gifts', initial_prompt: '“〇〇，早安。”', ai_role: '你是刚旅行回来的同事。你正在把假期买的伴手礼送给对方。请谦虚地说：“前阵子谢谢你帮忙。这个是旅行的伴手礼，一点小意思，请大家尝尝。”' },
